class Campaign(BaseModel):
    model_config = ConfigDict(
        extra="allow",
        populate_by_name=True,
    )
    id: int | None = None
    alias: str | None = Field(None, description="Leave empty to generate automatically.")
    type: Literal["position", "weight"] | None = Field(
        "position", description="Set 'weight' to enable split-testing the flows."
    )
    name: str | None = None
    cookies_ttl: int | None = 24
    position: int | None = None
    state: Literal["active", "disabled", "deleted"] | None = "active"
    cost_type: Literal["CPM", "CPC", "CPUC", "RevShare", "CPA", "CPS", "CPUV", "CPV"] | None = "CPC"
    cost_value: float | None = 0
    cost_currency: str | None = Field(None, description="Leave empty to use tracker currency")
    group_id: int | None = None
    bind_visitors: Literal["s", "sl", "slo"] | None = Field(
        None,
        description="'s' for flows. 'sl' for flows and landing pages. 'slo' for flows, landing pages and offers.",
    )
    traffic_source_id: int | None = None
    token: str | None = None
    cost_auto: bool | None = False
    parameters: SourceParameters | None = None
    postbacks: list[S2SPostback] | None = None
    notes: str | None = None
    created_at: str | None = None
    updated_at: str | None = None


class CampaignCostRequest(BaseModel):
    model_config = ConfigDict(
        extra="allow",
        populate_by_name=True,
    )
    start_date: str = Field(..., description='Start date and time. For example, "2017-09-10 20:10"')
    end_date: str = Field(..., description='End date and time. For example, "2017-09-10 20:10"')
    timezone: str = Field(
        ..., description='Timezone for the time range. For example, "Europe/Madrid".'
    )
    cost: str = Field(..., description='Cost for the time range. For example, "19.22".')
    currency: str = Field(..., description='Currency of cost. For example "EUR".')
    only_campaign_uniques: bool | None = Field(
        None, description="Apply new costs to unique clicks only."
    )
    filters: FilterCostRequest | None = None


class CampaignRequest(BaseModel):
    model_config = ConfigDict(
        extra="allow",
        populate_by_name=True,
    )
    alias: str | None = Field(
        None, description="Campaign Alias which is Used in URL http://domain.com/ALIAS"
    )
    type: Literal["position", "weight"] | None = Field(
        "position", description="Flow  Rotation Type"
    )
    name: str | None = Field(None, description="Campaign Name")
    cookies_ttl: int | None = Field(
        24, description="When the Click Gets Unique Status Again, in Hours"
    )
    state: Literal["active", "disabled", "deleted"] | None = Field(
        "active", description="Campaign State"
    )
    cost_type: Literal["CPC", "CPUC", "CPM"] | None = Field("CPC", description="Cost Type")
    cost_value: float | None = Field(None, description="Cost Value")
    cost_currency: str | None = Field(
        None,
        description="Currency Value EUR/USD/RUB/UAH/GBP. Default Value is Taken from the Tracker's Settings.",
    )
    cost_auto: bool | None = Field(False, description="Enable Automatic Costs (0/1)")
    group_id: str | None = Field(None, description="Campaign Group ID")
    bind_visitors: str | None = Field(
        None,
        description="Bind Visitors Feature (null - disabled/ s - only to streams/ sl - to streams and LPs/ slo — to streams, LPs and offers)",
    )
    traffic_source_id: int | None = Field(None, description="Traffic source ID")
    parameters: SourceParameters | None = None
    token: str | None = Field(None, description="Token to gain access to Click API")
    domain_id: int | None = Field(None, description="Domain ID")
    postbacks: list[S2SPostback] | None = Field(None, description="Campaign S2S postback")
    notes: str | None = Field(None, description="Notes for the campaign")


