class StreamObject(BaseModel):
    model_config = ConfigDict(
        extra="allow",
        populate_by_name=True,
    )
    campaign_id: int | None = Field(None, description="Campaign ID")
    type: Literal["forced", "regular", "default"] | None = Field(None, description="Flow type")
    name: str | None = Field(None, description="Flow name")
    position: int | None = Field(None, description="Position of a flow among other flows.")
    weight: float | None = Field(None, description="Flow weight.")
    action_options: dict[str, Any] | None = Field(None, description="Action options.")
