    filter_or: bool | None = Field(False, description="Use 'OR' operator between filters")
    filters: list[FilterStreamRequest] | None = None
    triggers: list[TriggersStreamRequest] | None = None
    landings: list[LandingStreamRequest] | None = None
    offers: list[OfferStreamRequest] | None = None


